// Configuración por marca. Edita aquí: público, reglas de la marca y keywords base que siempre se miden.
// gsc: la propiedad de Search Console tal como aparece en Search Console («sc-domain:tu-dominio.com» o «https://www.tu-dominio.com/»).
// competidores: dominios (o parte) que quieres ver si aparecen en el top 10.
// On-page y propuestas de Claude: cada dos semanas contando desde BASE_ONPAGE. «Probar» corre todo.
const BASE_ONPAGE = '2027-01-04';
const MARCAS = {
  'marca-a': { nombre: 'Marca A', dominio: '__DOMINIO_A__', gsc: '__GSC_SITIO_A__', competidores: [],
    publico: 'describe aquí a quién le vende la marca',
    reglas: 'Escribe aquí las reglas de la marca: palabras prohibidas, promesas que no se pueden hacer, tono.',
    keywords_base: [] },
  'marca-b': { nombre: 'Marca B', dominio: '__DOMINIO_B__', gsc: '__GSC_SITIO_B__', competidores: [],
    publico: 'describe aquí a quién le vende la marca',
    reglas: 'Escribe aquí las reglas de la marca: palabras prohibidas, promesas que no se pueden hacer, tono.',
    keywords_base: [] },
};
const hoy = $now.setZone('America/Mexico_City').startOf('day');
const d = n => hoy.minus({ days: n }).toISODate();
let programado = false;
try { programado = $('Cada lunes 7:43').isExecuted === true; } catch (e) {}
const semanas = Math.round(hoy.diff(DateTime.fromISO(BASE_ONPAGE, { zone: 'America/Mexico_City' }), 'days').days / 7);
const toca = ((semanas % 2) + 2) % 2 === 0;
const onpage = !programado || toca;
const prox = hoy.startOf('week').plus({ weeks: toca ? 2 : 1 });
return [{ json: {
  MARCAS, fecha: hoy.toISODate(), semana: hoy.toFormat("kkkk-'W'WW"),
  gsc: { ini: d(9), fin: d(3), antIni: d(16), antFin: d(10), ini28: d(30), fin28: d(3) },
  programado, onpage, proximoOnpage: prox.toISODate(),
} }];

// Tres consultas por marca: semana (búsqueda + página), semana anterior (búsqueda) y 28 días por página.
const F = $('Marcas').first().json;
const out = [];
for (const [marca, c] of Object.entries(F.MARCAS)) {
  const url = 'https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(c.gsc) + '/searchAnalytics/query';
  out.push({ json: { marca, tipo: 'semana', url, body: { startDate: F.gsc.ini, endDate: F.gsc.fin, dimensions: ['query', 'page'], rowLimit: 1000 } } });
  out.push({ json: { marca, tipo: 'anterior', url, body: { startDate: F.gsc.antIni, endDate: F.gsc.antFin, dimensions: ['query'], rowLimit: 1000 } } });
  out.push({ json: { marca, tipo: 'paginas', url, body: { startDate: F.gsc.ini28, endDate: F.gsc.fin28, dimensions: ['page'], rowLimit: 500 } } });
  out.push({ json: { marca, tipo: 'sitemap', url: 'https://' + String(c.dominio).replace(/^https?:\/\//, '').replace(/\/$/, '') + '/sitemap.xml', body: null } });
}
return out;

// Keywords a medir: artículos (seo_articulos), pestaña Keywords y las keywords base de cada marca.
const F = $('Marcas').first().json;
const MAX = 40;
const norm = s => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
const lista = Object.fromEntries(Object.keys(F.MARCAS).map(m => [m, new Map()]));
const add = (marca, kw, origen, volumen) => {
  const k = norm(kw);
  if (!k || !lista[marca] || lista[marca].has(k)) return;
  lista[marca].set(k, { marca, keyword: k, origen, volumen: volumen === null || volumen === undefined ? '' : volumen });
};
for (const it of $('Leer seo_articulos').all()) { const r = it.json || {}; add(r.marca, r.keyword, r.estado === 'publicado' ? 'artículo publicado' : 'artículo planeado', r.volumen); }
for (const r of (($('Leer Keywords').first().json || {}).values || []).slice(1)) add(r[1], r[2], 'pestaña Keywords', r[5]);
for (const [marca, c] of Object.entries(F.MARCAS)) for (const k of c.keywords_base || []) add(marca, Array.isArray(k) ? k[0] : k, 'base', Array.isArray(k) ? k[1] : '');
const out = [];
for (const m of Object.values(lista)) out.push(...[...m.values()].slice(0, MAX));
if (!out.length) throw new Error('No hay keywords que medir: agrega filas a la pestaña Keywords o keywords_base en «Marcas».');
return out.map(j => ({ json: j }));

// Páginas a revisar: sitemap + artículos publicados + páginas con impresiones en Search Console.
// Las páginas legales (privacidad, términos, aviso, cookies) nunca se revisan ni se cambian.
const F = $('Marcas').first().json;
const esLegal = u => { let s = String(u || ''); try { s = decodeURIComponent(s); } catch (e) {} const p = s.replace(/^https?:\/\/[^\/?#]+/i, '').toLowerCase(); return /\/(?:[^\/?#]*privacidad[^\/?#]*|privacy[^\/?#]*|t[eé]rminos[^\/?#]*|terms[^\/?#]*|aviso(?:-[^\/?#]*)?|legal(?:es)?|cookies)(?:\/|$|[?#])/.test(p); };
const limpia = u => { const m = String(u || '').match(/^(https?:\/\/[^\/?#]+)([^?#]*)/i); return m ? (m[1].toLowerCase() + m[2]).replace(/\/$/, '') : null; };
const marcas = Object.keys(F.MARCAS);
const urls = Object.fromEntries(marcas.map(m => [m, new Set()]));
const enSitemap = Object.fromEntries(marcas.map(m => [m, new Set()]));
const sm = $('¿Solo sitemaps?').all().map(i => i.json), smr = $('Sitemaps').all().map(i => i.json);
sm.forEach((s, i) => { const xml = String((smr[i] || {}).data || ''); for (const m of xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)) { const u = limpia(m[1]); if (u) { urls[s.marca].add(u); enSitemap[s.marca].add(u); } } });
for (const it of $('Leer seo_articulos').all()) { const r = it.json || {}; if (r.estado === 'publicado' && r.url && urls[r.marca]) { const u = limpia(r.url); if (u) urls[r.marca].add(u); } }
const pedidos = $('¿Solo Search Console?').all().map(i => i.json), gsc = $('Search Console').all().map(i => i.json);
pedidos.forEach((p, i) => { if (p.tipo !== 'paginas') return; for (const r of ((gsc[i] || {}).rows || [])) { const u = limpia(r.keys[0]); if (u && r.impressions >= 5) urls[p.marca].add(u); } });
const omitir = /\/(checkout|order-confirmation|paypal-checkout|401|404)$/;
const out = [];
for (const marca of marcas) for (const u of [...urls[marca]].filter(u => !omitir.test(u) && !esLegal(u)).slice(0, 40)) out.push({ json: { marca, url: u, en_sitemap: enSitemap[marca].has(u) } });
return out;

// Junta posiciones (DataForSEO), Search Console y on-page. Un item por marca con filas para el Sheet,
// el texto del reporte y el pedido a Claude.
const F = $('Marcas').first().json;
const MARCAS = F.MARCAS;
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = n => Number(n || 0).toLocaleString('es-MX', { maximumFractionDigits: 0 });
const limpia = u => { const m = String(u || '').match(/^(https?:\/\/[^\/?#]+)([^?#]*)/i); return m ? (m[1].toLowerCase() + m[2]).replace(/\/$/, '') : null; };
const corta = u => String(u || '').replace(/^https?:\/\/(www\.)?/, '').replace(/^[^/]+/, '') || '/';
const normUrl = u => { let s = limpia(u) || ''; try { s = decodeURIComponent(s); } catch (err) {} return s.toLowerCase(); };
const leer = n => { try { return $(n).first().json; } catch (err) { return {}; } };
const R = {};
for (const m of Object.keys(MARCAS)) R[m] = { filasPos: [], filasOn: [], pos: [], paginas: [], errores: [], redirigen: [], costo: 0 };

// Historial: última posición guardada por marca + keyword antes de hoy.
const prev = {};
for (const r of (leer('Leer historial').values || []).slice(1)) {
  const [fecha, , marca, kw, , , posicion] = r;
  if (!fecha || fecha >= F.fecha) continue;
  const k = marca + '|' + kw;
  if (!prev[k] || prev[k].fecha <= fecha) prev[k] = { fecha, posicion: posicion === '' || posicion === undefined ? null : Number(posicion) };
}

// Search Console.
const G = {};
for (const m of Object.keys(MARCAS)) G[m] = { error: null, q: {}, a: {}, paginas: [] };
const pedidos = $('¿Solo Search Console?').all().map(i => i.json), resp = $('Search Console').all().map(i => i.json || {});
pedidos.forEach((p, i) => {
  const r = resp[i] || {}, g = G[p.marca]; if (!g) return;
  if (r.error) { g.error = r.error.message || r.error.status || 'error'; return; }
  if (p.tipo === 'semana') for (const x of r.rows || []) {
    const [query, page] = x.keys;
    const y = g.q[query] || (g.q[query] = { c: 0, i: 0, pw: 0, page, pi: 0 });
    y.c += x.clicks; y.i += x.impressions; y.pw += x.position * x.impressions;
    if (x.impressions > y.pi) { y.pi = x.impressions; y.page = page; }
  }
  if (p.tipo === 'anterior') for (const x of r.rows || []) g.a[x.keys[0]] = { c: x.clicks, i: x.impressions, pos: x.position };
  if (p.tipo === 'paginas') g.paginas = (r.rows || []).map(x => ({ url: limpia(x.keys[0]), c: x.clicks, i: x.impressions, ctr: x.ctr, pos: x.position }));
});
for (const g of Object.values(G)) for (const y of Object.values(g.q)) y.pos = y.i ? y.pw / y.i : null;

// Posiciones en Google (DataForSEO). A veces el dominio viene como google.com.mx/goto: se toma de breadcrumb.
const dom = d => String(d || '').replace(/^www\./, '').toLowerCase();
const real = x => {
  const d = dom(x.domain);
  if (d && !/^google\.[a-z.]+$/.test(d) && !/google\.[a-z.]+\/goto/.test(String(x.url || ''))) return { d, url: x.url || '' };
  const m = String(x.breadcrumb || '').match(/^https?:\/\/([^\s\/›]+)/i);
  return m ? { d: dom(m[1]), url: 'https://' + m[1].toLowerCase() } : { d: '', url: '' };
};
const kws = $('Keywords a medir').all();
$('Google (DataForSEO)').all().forEach((it, i) => {
  const base = (kws[i] && kws[i].json) || {};
  const t = (it.json.tasks || [])[0] || {};
  const marca = (t.data && t.data.tag) || base.marca;
  const cfg = MARCAS[marca]; if (!cfg) return;
  const r = R[marca];
  r.costo += Number(t.cost || 0);
  const kw = base.keyword || (t.data && t.data.keyword);
  if (t.status_code !== 20000) { r.errores.push(`${kw}: ${t.status_message || (it.json.error && it.json.error.message) || 'sin respuesta'}`); return; }
  const items = (((t.result || [])[0] || {}).items || []).filter(x => x.type === 'organic').map(x => { const rr = real(x); return Object.assign({}, x, { domReal: rr.d, urlReal: rr.url }); });
  const g = G[marca].q[kw];
  const dominio = dom(String(cfg.dominio).replace(/^https?:\/\//, '').replace(/\/.*$/, ''));
  const nuestro = items.find(x => x.domReal.endsWith(dominio));
  const pos = nuestro ? nuestro.rank_group : null;
  const urlNuestra = nuestro ? (nuestro.urlReal.split('/').length > 3 ? nuestro.urlReal : ((g && g.page) || nuestro.urlReal)) : '';
  const p = prev[marca + '|' + kw];
  const posAnt = p ? p.posicion : null;
  let cambio = 'primera medición';
  if (p) {
    if (pos && posAnt) cambio = posAnt === pos ? '=' : (posAnt > pos ? `▲${posAnt - pos}` : `▼${pos - posAnt}`);
    else if (pos && !posAnt) cambio = 'entró';
    else if (!pos && posAnt) cambio = 'salió';
    else cambio = 'sigue fuera';
  }
  const top = items.slice(0, 3).map(x => x.domReal);
  const comp = (cfg.competidores || []).length ? [...new Set(items.filter(x => x.rank_group <= 10 && cfg.competidores.some(c => x.domReal.includes(c))).map(x => x.domReal))] : [];
  r.pos.push({ kw, pos, posAnt, cambio, url: urlNuestra, volumen: base.volumen, top, comp });
  r.filasPos.push([F.fecha, F.semana, marca, kw, base.origen || '', base.volumen ?? '', pos ?? '', posAnt ?? '', cambio,
    urlNuestra, top[0] || '', top[1] || '', top[2] || '', comp.join(', '), g ? g.c : '', g ? g.i : '', g && g.pos ? Math.round(g.pos * 10) / 10 : '']);
});

// On-page (solo si toca).
const pags = F.onpage ? $('Páginas a revisar').all() : [];
const audit = [], titulos = {};
(F.onpage ? $('On-page (DataForSEO)').all() : []).forEach((it, i) => {
  const base = (pags[i] && pags[i].json) || {};
  const marca = base.marca; if (!R[marca]) return;
  const t = (it.json.tasks || [])[0] || {};
  R[marca].costo += Number(t.cost || 0);
  const x = t.status_code === 20000 ? ((((t.result || [])[0] || {}).items || [])[0]) : null;
  if (!x) { audit.push({ marca, base, error: t.status_message || (it.json.error && it.json.error.message) || 'sin respuesta' }); return; }
  // Si la URL redirige, no se revisa (DataForSEO reportaría la página destino).
  const sc0 = Number(x.status_code) || 0;
  if ((sc0 >= 300 && sc0 < 400) || x.location || x.redirect_url || (x.checks && x.checks.is_redirect) || (x.url && normUrl(x.url) !== normUrl(base.url))) { R[marca].redirigen.push({ url: base.url }); return; }
  audit.push({ marca, base, x });
  const ti = (x.meta && x.meta.title) || '';
  titulos[marca] = titulos[marca] || {};
  (titulos[marca][ti] = titulos[marca][ti] || []).push(base.url);
});
const PRIO = ['ok', 'baja', 'media', 'alta'];
for (const a of audit) {
  const P = []; let prio = 0;
  const add = (txt, p) => { P.push(txt); prio = Math.max(prio, p); };
  const gp = G[a.marca].paginas.find(p => p.url === a.base.url);
  let fila = { status: '', score: '', titulo: '', tl: '', dl: '', h1: '', palabras: '', seg: '', descripcion: '' };
  if (a.error) add('No se pudo revisar: ' + a.error, 1);
  else {
    const x = a.x, m = x.meta || {}, c = x.checks || {};
    const sc = x.status_code, tl = m.title_length ?? (m.title || '').length, dl = m.description_length ?? (m.description || '').length;
    const h1 = (m.htags && m.htags.h1) || [];
    const palabras = m.content ? m.content.plain_text_word_count : null;
    const seg = x.page_timing && x.page_timing.duration_time ? x.page_timing.duration_time / 1000 : null;
    fila = { status: sc, score: x.onpage_score != null ? Math.round(x.onpage_score) : '', titulo: m.title || '', tl, dl, h1: h1[0] || '', palabras: palabras ?? '', seg: seg ? Math.round(seg * 10) / 10 : '', descripcion: m.description || '' };
    if (sc >= 400) add(`La página responde ${sc}`, 3);
    if (!m.title) add('Sin título', 3);
    else if (tl > 60) add(`Título largo (${tl} caracteres; Google corta cerca de 60)`, 2);
    else if (tl < 30) add(`Título corto (${tl} caracteres)`, 1);
    if (!m.description) add('Sin meta descripción', 2);
    else if (dl > 160) add(`Descripción larga (${dl} caracteres)`, 1);
    else if (dl < 70) add(`Descripción corta (${dl} caracteres)`, 1);
    if (!h1.length) add('Sin H1', 2);
    else if (h1.length > 1) add(`${h1.length} H1 (debe haber uno)`, 1);
    if (m.title && (titulos[a.marca][m.title] || []).length > 1) add('Título repetido en otra página', 2);
    if (palabras != null && palabras < 300) add(`Poco texto (${palabras} palabras)`, 1);
    if (c.no_image_alt) add('Imágenes sin texto alternativo', 1);
    if (seg && seg > 3) add(`Carga lenta (${seg.toFixed(1)} s)`, 2);
    if (m.canonical && limpia(m.canonical) && limpia(m.canonical) !== a.base.url) add('El canonical apunta a otra URL', 2);
    if (sc === 200 && !a.base.en_sitemap) add('No está en el sitemap', 2);
  }
  if (gp && gp.i >= 50 && gp.pos <= 15 && gp.ctr < 0.02) add(`CTR bajo en Google: ${(gp.ctr * 100).toFixed(1)}% con ${gp.i} impresiones (posición ${gp.pos.toFixed(1)})`, 3);
  R[a.marca].paginas.push({ url: a.base.url, prio, problemas: P, gsc: gp || null, ...fila });
  R[a.marca].filasOn.push([F.fecha, F.semana, a.marca, a.base.url, fila.status, fila.score, fila.titulo, fila.tl, fila.dl, fila.h1, fila.palabras, fila.seg, P.join('; '), PRIO[prio], gp ? gp.i : '']);
}

return Object.entries(MARCAS).map(([marca, cfg]) => {
  const r = R[marca], g = G[marca];
  let t = `🔎 <b>SEO semanal · ${e(cfg.nombre)}</b>\n${F.semana}\n`;
  const en = (a, b) => r.pos.filter(p => p.pos && p.pos >= a && p.pos <= b).length;
  t += `\n<b>Posiciones en Google</b> (${r.pos.length} keywords, top 30)\nTop 3: ${en(1, 3)} · Top 10: ${en(1, 10)} · 11–30: ${en(11, 30)} · No aparecemos: ${r.pos.filter(p => !p.pos).length}\n`;
  const mejores = r.pos.filter(p => p.pos).sort((a, b) => a.pos - b.pos).slice(0, 6);
  if (mejores.length) t += 'Mejores: ' + mejores.map(p => `«${e(p.kw)}» #${p.pos}`).join(', ') + '\n';
  const subieron = r.pos.filter(p => p.pos && p.posAnt && p.pos < p.posAnt).sort((a, b) => (b.posAnt - b.pos) - (a.posAnt - a.pos)).slice(0, 5);
  const bajaron = r.pos.filter(p => p.posAnt && (!p.pos || p.pos > p.posAnt)).slice(0, 5);
  if (subieron.length) t += '▲ ' + subieron.map(p => `«${e(p.kw)}» ${p.posAnt}→${p.pos}`).join(', ') + '\n';
  if (bajaron.length) t += '▼ ' + bajaron.map(p => `«${e(p.kw)}» ${p.posAnt}→${p.pos || 'fuera'}`).join(', ') + '\n';
  if (r.pos.length && r.pos.every(p => p.cambio === 'primera medición')) t += 'Primera medición: la comparación empieza la próxima semana.\n';
  const comps = [...new Set(r.pos.flatMap(p => p.comp))];
  if (comps.length) t += `Competencia en el top 10: ${e(comps.join(', '))}\n`;
  if (r.errores.length) t += `⚠️ No se pudieron medir ${r.errores.length} keywords.\n`;
  t += `\n<b>Search Console</b> (${F.gsc.ini.slice(5)} a ${F.gsc.fin.slice(5)})\n`;
  if (g.error) t += `⚠️ No se pudo leer: ${e(g.error)}\n`;
  else {
    const qs = Object.entries(g.q);
    const c = qs.reduce((s, [, x]) => s + x.c, 0), i = qs.reduce((s, [, x]) => s + x.i, 0);
    const ca = Object.values(g.a).reduce((s, x) => s + x.c, 0), ia = Object.values(g.a).reduce((s, x) => s + x.i, 0);
    t += `Clics ${num(c)} (antes ${num(ca)}) · Impresiones ${num(i)} (antes ${num(ia)})\n`;
    const top = qs.sort((a, b) => b[1].i - a[1].i).slice(0, 5);
    t += top.length ? 'Búsquedas: ' + top.map(([q, x]) => `«${e(q)}» ${x.c}/${num(x.i)} pos ${x.pos ? x.pos.toFixed(1) : '–'}`).join(', ') + '\n' : 'Todavía sin búsquedas registradas.\n';
  }
  if (F.onpage) {
    const alta = r.paginas.filter(p => p.prio === 3).length, media = r.paginas.filter(p => p.prio === 2).length;
    t += `\n<b>Revisión on-page</b>: ${r.paginas.length} páginas · ${alta} prioridad alta · ${media} media\n`;
    for (const p of [...r.paginas].sort((a, b) => b.prio - a.prio).filter(p => p.prio >= 2).slice(0, 6)) t += `• ${e(corta(p.url))}: ${e(p.problemas.slice(0, 3).join('; '))}\n`;
    if (r.redirigen.length) t += `• No se revisaron ${r.redirigen.length} URLs que redirigen.\n`;
  } else t += `\n<b>Revisión on-page</b>: cada dos semanas; la última sigue en el Sheet. Próxima: ${F.proximoOnpage}.\n`;
  const paraClaude = [...r.paginas].sort((a, b) => b.prio - a.prio || ((b.gsc && b.gsc.i) || 0) - ((a.gsc && a.gsc.i) || 0)).slice(0, 10).map(p => ({
    url: p.url, titulo: p.titulo, descripcion: p.descripcion, h1: p.h1, palabras: p.palabras, problemas: p.problemas,
    google_28d: p.gsc ? { clics: p.gsc.c, impresiones: p.gsc.i, ctr: Math.round(p.gsc.ctr * 1000) / 10, posicion: Math.round(p.gsc.pos * 10) / 10 } : null,
    busquedas: Object.entries(g.q).filter(([, x]) => limpia(x.page) === p.url).sort((a, b) => b[1].i - a[1].i).slice(0, 5).map(([q, x]) => ({ q, impresiones: x.i, posicion: x.pos ? Math.round(x.pos * 10) / 10 : null })),
  }));
  const cerca = r.pos.filter(p => p.pos && p.pos >= 4 && p.pos <= 30).map(p => ({ keyword: p.kw, posicion: p.pos, url: p.url, volumen: p.volumen }));
  const sinPagina = r.pos.filter(p => !p.pos && Number(p.volumen) >= 100).map(p => ({ keyword: p.kw, volumen: p.volumen }));
  const prompt = `Marca: ${cfg.nombre} (${cfg.dominio}). Público: ${cfg.publico}.\nReglas de la marca (obligatorias): ${cfg.reglas}\n\n` +
    'Tarea: propone como máximo 5 cambios on-page con el mayor impacto esperado. Prioriza páginas con impresiones en Google y keywords en posiciones 4 a 30. ' +
    'Cada cambio debe poder aplicarse tal cual: un título de máximo 60 caracteres, una meta descripción de 120 a 155 caracteres, un solo H1, o una instrucción concreta de contenido o enlace interno (qué texto y hacia qué URL). ' +
    'Usa solo los datos de abajo: no inventes cifras, precios ni promesas de posición. Escribe en español de México. ' +
    'Responde SOLO con JSON válido, sin texto adicional: {"cambios":[{"url":"","cambio":"titulo|descripcion|h1|contenido|enlace_interno|tecnico","actual":"","propuesta":"","por_que":""}]}\n\n' +
    'Páginas revisadas:\n' + JSON.stringify(paraClaude) + '\n\nKeywords en posiciones 4 a 30:\n' + JSON.stringify(cerca) + '\n\nKeywords con búsquedas donde no aparecemos:\n' + JSON.stringify(sinPagina);
  return { json: { marca, nombre: cfg.nombre, texto: t, prompt, filasPos: r.filasPos, filasOn: r.filasOn, costo: Math.round(r.costo * 10000) / 10000 } };
});

// Junta el análisis con las propuestas de Claude: filas para el Sheet y mensajes de Telegram.
// Las propuestas quedan «propuesto»: se aprueban o descartan en el panel (pestaña SEO) y se aplican a mano en el sitio.
const esLegal = u => { let s = String(u || ''); try { s = decodeURIComponent(s); } catch (e) {} const p = s.replace(/^https?:\/\/[^\/?#]+/i, '').toLowerCase(); return /\/(?:[^\/?#]*privacidad[^\/?#]*|privacy[^\/?#]*|t[eé]rminos[^\/?#]*|terms[^\/?#]*|aviso(?:-[^\/?#]*)?|legal(?:es)?|cookies)(?:\/|$|[?#])/.test(p); };
const F = $('Marcas').first().json;
const SHEET = 'https://docs.google.com/spreadsheets/d/__SHEET_ID__/edit';
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = u => String(u || '').replace(/^https?:\/\/(www\.)?/, '').replace(/^[^/]+/, '') || '/';
const sinHtml = s => String(s || '').replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const limpiar = [];
try { ($('Leer historial').first().json.values || []).forEach((r, i) => { if (i > 0 && r[0] === F.fecha) limpiar.push(`'SEO posiciones'!A${i + 1}:Q${i + 1}`); }); } catch (err) {}
const an = $('Analizar').all();
let cl = [];
try { if (F.onpage) cl = $('Claude propone cambios').all(); } catch (err) {}
const salida = { filasPos: [], filasOn: [], filasProp: [], filasRep: [], mensajes: [], limpiar };
an.forEach((it, i) => {
  const a = it.json;
  const c = (cl[i] && cl[i].json) || {};
  let cambios = [], errorClaude = null;
  if (F.onpage) {
    if (c.error || !c.content) errorClaude = (c.error && (c.error.message || c.error.type)) || 'sin respuesta';
    else {
      const txt = (c.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
      const m = txt.match(/\{[\s\S]*\}/);
      try { cambios = (JSON.parse(m ? m[0] : txt).cambios || []).filter(x => x && !esLegal(x.url)).slice(0, 5); } catch (err) { errorClaude = 'respuesta no legible'; }
    }
  }
  let t = a.texto;
  if (F.onpage) {
    t += `\n<b>Cambios propuestos</b> (apruébalos o descártalos en el panel, pestaña SEO; no se aplica nada solo)\n`;
    if (errorClaude) t += `⚠️ No se pudieron generar: ${e(errorClaude)}\n`;
    else if (!cambios.length) t += 'Sin cambios propuestos esta vez.\n';
  }
  cambios.forEach((x, k) => {
    const prop = String(x.propuesta || '');
    t += `${k + 1}. <b>${e(x.cambio)}</b> en ${e(corta(x.url))}\n   → ${e(prop.length > 260 ? prop.slice(0, 257) + '…' : prop)}\n`;
    salida.filasProp.push([F.fecha, F.semana, a.marca, x.url || '', x.cambio || '', x.actual || '', x.propuesta || '', x.por_que || '', 'propuesto']);
  });
  t += `\nCosto DataForSEO: US$${a.costo}\n<a href="${SHEET}">Ver detalle en el Sheet</a> (pestañas SEO)`;
  if (t.length > 3900) { let corto = ''; for (const linea of t.split('\n')) { if ((corto + linea).length > 3700) break; corto += linea + '\n'; } t = corto + `…\n<a href="${SHEET}">Sigue en el Sheet</a>`; }
  salida.filasPos.push(...a.filasPos);
  salida.filasOn.push(...a.filasOn);
  salida.filasRep.push([F.fecha, F.semana, a.marca, sinHtml(t), a.costo]);
  salida.mensajes.push({ marca: a.marca, texto: t });
});
return [{ json: salida }];
